package steps

import (
	"fmt"
	"os/exec"
	"strconv"
	"strings"
)

//truebdd:concept when "running"
func conceptd811179f54fc202f6e4c73986e6f62affb7dc33a44ca0b952e967cf7a999da3d(state *State, args []string) error {
	const hostRoot = "../.."
	if state.Program == "" {
		return fmt.Errorf("the calculator is not installed")
	}
	calculatorCommand := args[0]
	number := args[1]
	if _, err := strconv.Atoi(number); err != nil {
		return fmt.Errorf("the step's number %q is not a whole number: %w", number, err)
	}
	process := exec.Command(state.Program, calculatorCommand, number)
	process.Dir = hostRoot
	output, err := process.Output()
	if err != nil {
		return fmt.Errorf("run %q on %s: %w", calculatorCommand, number, err)
	}
	value, err := strconv.Atoi(strings.TrimSpace(string(output)))
	if err != nil {
		return fmt.Errorf("read the integer stdout of %q on %s: %q: %w", calculatorCommand, number, output, err)
	}
	state.Value = value
	return nil
}

package steps

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
)

func Register(suite Registrar) {
	suite.Step(`^the calculator is installed$`, installed)
	suite.Step(`^the result is (-?\d+)$`, result)

	suite.Step("^the Owner runs \"([^\"]+)\" on (-?\\d+)$", conceptd811179f54fc202f6e4c73986e6f62affb7dc33a44ca0b952e967cf7a999da3d)
}

//truebdd:concept given "installation"
func installed(state *State, _ []string) error {
	program, err := filepath.Abs("../../tmp/calc-program/calc")
	if err != nil {
		return err
	}
	if err = os.MkdirAll(filepath.Dir(program), 0o755); err != nil {
		return err
	}
	command := exec.Command("go", "build", "-o", program, "./services/calc")
	command.Dir = "../.."
	if output, err := command.CombinedOutput(); err != nil {
		return fmt.Errorf("install the calculator: %w: %s", err, output)
	}
	state.Program = program
	return nil
}

//truebdd:concept then "result"
func result(state *State, args []string) error {
	want, err := strconv.Atoi(args[0])
	if err != nil {
		return err
	}
	if state.Value != want {
		return fmt.Errorf("expected %d, got %d", want, state.Value)
	}
	return nil
}
